INSERT INTO workflow.task_templates (id, stage_id, title, description, default_assigned_role, default_priority, estimated_duration_hours, display_order, is_active) VALUES (1, 1, 'Agendar reunión', 'Coordinar con el cliente fecha y hora de la reunión de planificación.', 'operations', 'high', 1, 1, true);
INSERT INTO workflow.task_templates (id, stage_id, title, description, default_assigned_role, default_priority, estimated_duration_hours, display_order, is_active) VALUES (4, 2, 'Envío de formulario', 'El cliente completa y envía el formulario con sus datos personales y de la LLC.', 'client', 'high', NULL, 1, true);
INSERT INTO workflow.task_templates (id, stage_id, title, description, default_assigned_role, default_priority, estimated_duration_hours, display_order, is_active) VALUES (5, 2, 'Validación de datos', 'Operaciones verifica completitud y consistencia de los datos del formulario.', 'operations', 'normal', 1, 2, true);
INSERT INTO workflow.task_templates (id, stage_id, title, description, default_assigned_role, default_priority, estimated_duration_hours, display_order, is_active) VALUES (6, 3, 'Incorporación ante el estado', 'Presentar la solicitud de incorporación ante la secretaría de estado correspondiente.', 'incorporator', 'high', 3, 1, true);
INSERT INTO workflow.task_templates (id, stage_id, title, description, default_assigned_role, default_priority, estimated_duration_hours, display_order, is_active) VALUES (7, 3, 'Artículos de incorporación', 'Redactar y cargar los artículos de incorporación en el módulo de documentos.', 'incorporator', 'high', 2, 2, true);
INSERT INTO workflow.task_templates (id, stage_id, title, description, default_assigned_role, default_priority, estimated_duration_hours, display_order, is_active) VALUES (8, 4, 'Verificar artículos de incorporación', 'Confirmar que los artículos de incorporación generados en la etapa anterior están correctos.', 'operations', 'normal', 1, 1, true);
INSERT INTO workflow.task_templates (id, stage_id, title, description, default_assigned_role, default_priority, estimated_duration_hours, display_order, is_active) VALUES (9, 4, 'Elaborar Operation Agreement', 'Redactar y cargar el Operation Agreement. Requerido en plan Estándar y Business.', 'operations', 'high', 3, 2, true);
INSERT INTO workflow.task_templates (id, stage_id, title, description, default_assigned_role, default_priority, estimated_duration_hours, display_order, is_active) VALUES (10, 5, 'Envío de documentos al cliente', 'Remitir al cliente todos los documentos listos para firma.', 'operations', 'high', 1, 1, true);
INSERT INTO workflow.task_templates (id, stage_id, title, description, default_assigned_role, default_priority, estimated_duration_hours, display_order, is_active) VALUES (11, 5, 'Validación y firma por el cliente', 'El cliente revisa y firma los documentos.', 'client', 'high', NULL, 2, true);
INSERT INTO workflow.task_templates (id, stage_id, title, description, default_assigned_role, default_priority, estimated_duration_hours, display_order, is_active) VALUES (12, 6, 'Preparar solicitud SS-4', 'Completar el formulario SS-4. En plan Business aplicar modalidad EIN acelerado.', 'operations', 'high', 2, 1, true);
INSERT INTO workflow.task_templates (id, stage_id, title, description, default_assigned_role, default_priority, estimated_duration_hours, display_order, is_active) VALUES (13, 6, 'Envío por Fax al IRS', 'Transmitir el formulario SS-4 al IRS por fax.', 'mailing', 'high', 1, 2, true);
INSERT INTO workflow.task_templates (id, stage_id, title, description, default_assigned_role, default_priority, estimated_duration_hours, display_order, is_active) VALUES (14, 6, 'Llamar al IRS (seguimiento)', 'Si no hay respuesta en 4 semanas, realizar llamada de seguimiento al IRS.', 'operations', 'normal', 1, 3, true);
INSERT INTO workflow.task_templates (id, stage_id, title, description, default_assigned_role, default_priority, estimated_duration_hours, display_order, is_active) VALUES (15, 6, 'EIN listo', 'Cargar el documento de confirmación del EIN en el módulo de documentos.', 'operations', 'high', 1, 4, true);
INSERT INTO workflow.task_templates (id, stage_id, title, description, default_assigned_role, default_priority, estimated_duration_hours, display_order, is_active) VALUES (16, 7, 'Preparar formulario FinCEN', 'Completar el formulario de registro de beneficiarios reales (BOIR) ante FinCEN.', 'operations', 'normal', 2, 1, true);
INSERT INTO workflow.task_templates (id, stage_id, title, description, default_assigned_role, default_priority, estimated_duration_hours, display_order, is_active) VALUES (17, 7, 'Registrar solicitud BOIR', 'Enviar el formulario completado al sistema de FinCEN y cargar confirmación.', 'operations', 'normal', 1, 2, true);
INSERT INTO workflow.task_templates (id, stage_id, title, description, default_assigned_role, default_priority, estimated_duration_hours, display_order, is_active) VALUES (18, 8, 'Agendamiento de reunión bancaria', 'Coordinar reunión con el banco (Mercury o Relay) para apertura de cuenta.', 'operations', 'high', 1, 1, true);
